using System;
using System.Collections;
using UnityEngine;
using UnityEngine.Events;

public static class InvokeAlternatives
{
	public enum InvokeType
	{
		Invoke,
		InvokeRepeating,
		All
	}

	private static Coroutine[] InvokeRoutine;

	private static Coroutine[] InvokeRepeatingRoutine;

	public static Coroutine InvokeRepeating(MonoBehaviour starterScript, float startDelay, float repeatDelay, UnityAction action)
	{
		Coroutine coroutine = starterScript.StartCoroutine(InvokeRepeatingCorout(startDelay, repeatDelay, action));
		InvokeRepeatingRoutine.ExtendArray(coroutine);
		return coroutine;
	}

	private static IEnumerator InvokeRepeatingCorout(float startDelay, float repeatDelay, UnityAction action)
	{
		yield return new WaitForSeconds(startDelay);
		action?.Invoke();
		int i = 0;
		while (i < 1)
		{
			yield return new WaitForSeconds(repeatDelay);
			action?.Invoke();
		}
	}

	public static Coroutine InvokeRealtime(MonoBehaviour starterScript, float delay, UnityAction action)
	{
		Coroutine coroutine = starterScript.StartCoroutine(InvokeCoroutRealtime(delay, action));
		InvokeRoutine.ExtendArray(coroutine);
		return coroutine;
	}

	private static IEnumerator InvokeCoroutRealtime(float delay, UnityAction action)
	{
		yield return new WaitForSecondsRealtime(delay);
		action.Execute();
	}

	public static Coroutine Invoke(MonoBehaviour starterScript, float delay, UnityAction action)
	{
		Coroutine coroutine = starterScript.StartCoroutine(InvokeCorout(delay, action));
		InvokeRoutine.ExtendArray(coroutine);
		return coroutine;
	}

	private static IEnumerator InvokeCorout(float delay, UnityAction action)
	{
		yield return new WaitForSeconds(delay);
		action.Execute();
	}

	public static Coroutine InvokeSystemAction(MonoBehaviour starterScript, float delay, Action action)
	{
		Coroutine coroutine = starterScript.StartCoroutine(InvokeCorout(delay, action));
		InvokeRoutine.ExtendArray(coroutine);
		return coroutine;
	}

	private static IEnumerator InvokeCorout(float delay, Action action)
	{
		yield return new WaitForSeconds(delay);
		action();
	}

	public static Coroutine InvokeAfterFrame(MonoBehaviour starterScript, UnityAction action, bool tryUsingWaitForFixedUpdate = false)
	{
		return starterScript.StartCoroutine(InvokeAfterFrame_Routine(action, 1, tryUsingWaitForFixedUpdate));
	}

	public static Coroutine InvokeAfterMultipleFrames(MonoBehaviour starterScript, int framesAmount, UnityAction action, bool tryUsingWaitForFixedUpdate = false)
	{
		return starterScript.StartCoroutine(InvokeAfterFrame_Routine(action, framesAmount, tryUsingWaitForFixedUpdate));
	}

	private static IEnumerator InvokeAfterFrame_Routine(UnityAction action, int framesAmount, bool tryUsingWaitForFixedUpdate)
	{
		yield return WaitForFrames(framesAmount, tryUsingWaitForFixedUpdate);
		action.Execute();
	}

	public static IEnumerator WaitOneFrame(bool tryUsingWaitForFixedUpdate = false)
	{
		yield return WaitForFrames(1, tryUsingWaitForFixedUpdate);
	}

	public static IEnumerator WaitForFrames(int framesAmount, bool tryUsingWaitForFixedUpdate = false)
	{
		for (int i = 0; i < framesAmount; i++)
		{
			yield return new WaitForEndOfFrame();
		}
	}

	public static void StopInvoke(MonoBehaviour stopperScript, InvokeType type)
	{
		switch (type)
		{
		case InvokeType.Invoke:
			InvokeRoutine.StopAll(stopperScript);
			break;
		case InvokeType.InvokeRepeating:
			InvokeRepeatingRoutine.StopAll(stopperScript);
			break;
		case InvokeType.All:
			StopInvoke(stopperScript, InvokeType.Invoke);
			StopInvoke(stopperScript, InvokeType.InvokeRepeating);
			break;
		}
	}
}
